create policy tax_self_file_select on public.tax_returns for select to authenticated using (service_type = 'self_file' and created_by_user_id = (select auth.uid()));
create policy tax_self_file_insert on public.tax_returns for insert to authenticated with check (service_type = 'self_file' and created_by_user_id = (select auth.uid()) and user_id is null and client_id is null and firm_id is null);
create policy tax_self_file_update on public.tax_returns for update to authenticated using (service_type = 'self_file' and created_by_user_id = (select auth.uid())) with check (service_type = 'self_file' and created_by_user_id = (select auth.uid()) and user_id is null and client_id is null and firm_id is null);
create policy tax_w2_self_file on public.tax_w2_income for all to authenticated using (exists (select 1 from public.tax_returns r where r.id = tax_return_id and r.service_type = 'self_file' and r.created_by_user_id = (select auth.uid()))) with check (exists (select 1 from public.tax_returns r where r.id = tax_return_id and r.service_type = 'self_file' and r.created_by_user_id = (select auth.uid())));
create policy tax_calculations_self_file_insert on public.tax_calculations for insert to authenticated with check (user_id = (select auth.uid()) and exists (select 1 from public.tax_returns r where r.id::text = calculation_data->>'returnId' and r.service_type = 'self_file' and r.created_by_user_id = (select auth.uid())));
alter policy auth_read_tax_calculations on public.tax_calculations using (user_id = (select auth.uid()));
create index if not exists tax_returns_self_file_owner_idx on public.tax_returns(created_by_user_id,updated_at desc) where service_type = 'self_file';
